package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StdDateFormat.setLenient(boolean)
 */
public class StdDateFormat_setLenient_TriageGen2Test {

    @Test
    public void testSetLenient_TrueToFalse_TriggersUpdate() {
        // Arrange: Start with lenient = true
        // Note: Default constructor usually initializes _lenient to true or false depending on version,
        // but we ensure we test the transition.
        StdDateFormat df = new StdDateFormat();
        df.setLenient(true);

        // Act: Change from true to false
        df.setLenient(false);

        // Assert
        assertFalse("Leniency should be false", df.isLenient());
    }

    @Test
    public void testSetLenient_FalseToTrue_TriggersUpdate() {
        // Arrange
        StdDateFormat df = new StdDateFormat();
        df.setLenient(false);

        // Act
        df.setLenient(true);

        // Assert
        assertTrue("Leniency should be true", df.isLenient());
    }

    @Test
    public void testSetLenient_SameValue_NoChange() {
        // Arrange
        StdDateFormat df = new StdDateFormat();
        boolean initialState = df.isLenient();

        // Act: Set to the same value it already has
        df.setLenient(initialState);

        // Assert
        assertEquals("Leniency should remain unchanged", initialState, df.isLenient());
    }

    @Test
    public void testSetLenient_WithConstructorInitialization() {
        // Testing the branch where initial state is set via protected constructor logic 
        // (simulated via public API)
        StdDateFormat df = new StdDateFormat(TimeZone.getDefault(), Locale.US);

        // Ensure we can toggle it
        boolean current = df.isLenient();
        df.setLenient(!current);
        assertEquals(!current, df.isLenient());
    }

    @Test
    public void testSetLenient_ToggleMultipleTimes() {
        // Arrange
        StdDateFormat df = new StdDateFormat();

        // Act & Assert
        df.setLenient(true);
        assertTrue(df.isLenient());

        df.setLenient(false);
        assertFalse(df.isLenient());

        df.setLenient(true);
        assertTrue(df.isLenient());
    }
}
